// Il detective ispeziona la memoria
DenseLayer* dense = dynamic_cast&lt;DenseLayer*&gt;(ptr); 

1if (dense != nullptr) {
    std::cout &lt;&lt; "Sì! È un DenseLayer. Aggiorno i pesi.\n";
    dense-&gt;getWeightsMatrix(); 
2} else {
    std::cout &lt;&lt; "Falso allarme. Era un altro tipo di Layer.\n";
}

